$\begin{align}
\dfrac{S(t+4)}{S(t)}&=0.\overline{3}
\\\\
\dfrac{\cancel C\cdot e^{k(t+4)}}{\cancel C\cdot e^{kt}}&=0.\overline{3}
\\\\
e^{kt+4 k-kt}&=0.\overline{3}
\\\\
e^{4 k}&=0.\overline{3}
\\\\
\ln\left(e^{4 k}\right)&=\ln(0.\overline{3})
\\\\
4 k&=\ln(0.\overline{3})
\\\\
k&=\dfrac{\ln(0.\overline{3})}{4}
\end{align}$
